def babylonian_squareroot(n):
    if n == 0:
        return 0

    # Initial guess for the square root
    x = n / 2.0

    # Iterative process to refine the guess
    while True:
        y = (x + n/x) / 2.0
        if abs(y - x) < 1e-6:
            break
        x = y

    return round(x, 6)
