def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        j = i - 1
        while j >= 0:
            if s[i-1] != s[j]:
                break
            j -= 1
        else:
            dp[i] = dp[i-1]

        j = i - 1
        while j < n:
            if s[i-1] != s[j]:
                break
            j += 1
        else:
            dp[i] = max(dp[i], dp[i-j])

    return dp[n]

