def count_bidirectional(lst):
    # Initialize counters for each direction of tuples
    left_count = right_count = 0

    # Iterate through the list to count bidirectional tuples
    for i in range(len(lst)):
        if i % 2 == 0:
            # Count elements on the left side of the tuple
            if lst[i] not in lst[:i]:
                left_count += 1
        else:
            # Count elements on the right side of the tuple
            if lst[i] not in lst[i+1:]:
                right_count += 1

    return str(left_count + right_count)
