def next_Power_Of_2(n):
    # If n is already a power of 2, return it directly
    if (n & (n - 1)) == 0:
        return n

    # Find the position where the binary representation ends
    pos = 0
    while (1 << pos) <= n:
        pos += 1

    # Calculate the next power of 2 by shifting left by one position
    return (1 << pos)
