def max_profit(stock_prices, k):
    if k >= len(stock_prices):
        return sum(max(stock_prices[i+1] - stock_prices[i] for i in range(len(stock_prices)-1))) 

    dp = [[0]*k for _ in range(k)]
    for price in stock_prices:
