def solve(A, B):
    # Count inversions in A
    inversions_A = 0
    for i in range(len(A)):
        for j in range(i+1, len(A)):
            if A[i] > A[j]:
                inversions_A += 1

    # Count inversions in B
    inversions_B = 0
    for i in range(len(B)):
        for j in range(i+1, len(B)):
            if B[i] > B[j]:
                inversions_B += 1

    return inversions_A == inversions_B
