def minimum_Length(s):
    # Initialize variables
    min_length = len(s)
    char_count = {}

    # Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the minimum length of the string that can be formed
    for char, count in char_count.items():
        if count > 1:
            min_length = min(min_length, len(s) - (count * (count + 1)) // 2)

    return min_length
```

