def max_volume(side_sum):
    # Initialize the maximum volume to 0
    max_volume = 0

    # Iterate through all possible combinations of dimensions (a, b, c)
    for a in range(1, side_sum // 3 + 1):
        for b in range(a, side_sum // 2 + 1):
            for c in range(b, side_sum - a + 1):
                # Calculate the volume of the cuboid
                volume = a * b * c

                # Update the maximum volume if the current one is greater
                if volume > max_volume:
                    max_volume = volume

    return max_volume
