def min_flip_to_make_string_alternate(s):
    # Count the frequency of each character in the string
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Initialize variables
    flip_count = 0
    max_char = max(char_count.values())

    # Iterate through the sorted list of frequencies
    for freq in sorted(char_count.values()):
