def permute_string(s):
    if len(s) == 1:
        return [s]

    result = []
    for i in range(len(s)):
        char = s[i]

        # Generate permutations excluding the current character
        remaining_chars = s[:i] + s[i+1:]
        for permutation in permute_string(remaining_chars):
            result.append(char + permutation)

    return result
