def is_subset_sum(nums, target, current_sum):
    # If the current sum exceeds the target or we have reached the end of the list,
    # return False if no valid subset exists, otherwise return True.
    if current_sum > target or len(nums) == 0:
        return False

    # Check if the current element can be added to the subset without exceeding the target.
    for i in range(len(nums)):
        if nums[i] <= current_sum - target:
            # Recursively check the rest of the list excluding the current element.
            return is_subset_sum(nums[:i] + nums[i+1:], target, current_sum - nums[i])

    # If all elements in the list satisfy the condition, return True.
    return True
```

