def modified_encode(lst):
    # Create a dictionary to map each character to its frequency
    freq = {char: lst.count(char) for char in set(lst)}

    # Initialize the result list
    res = []

    # Iterate over the characters in the input string
    for i, char in enumerate(lst):
        if char not in freq:
            # If the character does not exist in the frequency dictionary, add it as a new element
            res.append(freq[char])
        else:
            # Otherwise, append the current frequency of the character to the result list
            res.extend([freq[char]] * freq[char])

    return res
