def max_product(nums, k):
    # If k is greater than or equal to the length of nums, return the maximum product
    if k >= len(nums):
        return max(nums)

    # Initialize variables for the maximum and minimum products found so far
    max_product = float('-inf')
    min_product = float('inf')

    # Iterate through the first k elements of the list
    for i in range(k):
        # Update the maximum product if the current element is positive
        if nums[i] > 0:
            max_product = max(max_product * nums[i], nums[i])
        else:
            # Update the minimum product if the current element is negative
            min_product = min(min_product * nums[i], nums[i])

    # Return the maximum product found
    return max_product
```

