def heap_replace(heap, value):
    # Perform heapify operation on the heap
    for i in range(len(heap) // 2 - 1, -1, -1):
        max_heapify(heap, i)

    # Replace the smallest element with the new value
    heap[0] = value

    # Restore the heap property
    for i in range(len(heap) - 1, 0, -1):
        if heap[i][0] < heap[0][0]:
            heap[i], heap[0] = heap[0], heap[i]
            max_heapify(heap, 0)
def max_heapify(heap, i):
    left = 2 * i + 1
    right = 2 * i + 2
    largest = i

    if left < len(heap) and heap[left][0] > heap[largest][0]:
        largest = left

    if right < len(heap) and heap[right][0] > heap[largest][0]:
        largest = right

    if largest != i:
        heap[i], heap[largest] = heap[largest], heap[i]
        max_heapify(heap, largest)
```

