```python
def add_nested_tuples(tup1, tup2):
    # Flatten both tuples into lists
    flat_tup1 = [item for sublist in tup1 for item in sublist]
    flat_tup2 = [item for sublist in tup2 for item in sublist]

    # Add corresponding elements from both flattened lists
    result = []
    i = 0
    while i < len(flat_tup1) or i < len(flat_tup2):
        if i < len(flat_tup1):
            result.append(flat_tup1[i])
        if i < len(flat_tup2):
            result.append(flat_tup2[i])

        i += 1

    return tuple(result)
```

